def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """A quadratic equation for log10(|ID|/A) considering saturation behavior."""
    a, b, c, d = parameters
    return a + b * gate_voltage_abs + c * drain_voltage_abs**2 + d * (gate_voltage_abs * drain_voltage_abs)
